import json,base64,sys,re
def walk(p,out):
    b=p.get('body',{}).get('data')
    if b and p.get('mimeType','').startswith('text/plain'):
        out.append(base64.urlsafe_b64decode(b+'==').decode('utf-8','replace'))
    for c in p.get('parts',[]) or []: walk(c,out)
    if b and not out and p.get('mimeType','').startswith('text/html'):
        out.append(re.sub('<[^>]+>',' ',base64.urlsafe_b64decode(b+'==').decode('utf-8','replace')))
for f in sys.argv[1:]:
    d=json.load(open(f)); r=json.loads(d['result'])
    msgs=r.get('messages',[r])
    for m in msgs:
        h={x['name']:x['value'] for x in m['payload']['headers']}
        print('=== ',h.get('Date'),'|',h.get('From'),'->',h.get('To'),'cc',h.get('Cc'),'|',h.get('Subject'))
        out=[];walk(m['payload'],out)
        t='\n'.join(out)
        # strip quoted
        lines=[l for l in t.splitlines() if not l.startswith('>')]
        print('\n'.join(lines)[:4000])
EOF
